insert into drive_org_space_config (
    dept_id, enabled, quota_bytes, tree_budget_bytes, member_write_mode,
    lifecycle_status, config_source, version, create_by, create_time,
    update_by, update_time, remark
) values (
    #{deptId}, #{enabled}, #{quotaBytes}, #{treeBudgetBytes}, #{memberWriteMode},
    #{lifecycleStatus}, #{configSource}, #{version}, #{createBy}, #{createTime},
    #{updateBy}, #{updateTime}, #{remark}
)
